  ('8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', 'b2044359-9915-41b5-badd-087e8eb4ab2b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$Analyze the profound impact of the Battle of Kalinga on Emperor Ashoka, detailing the specific elements that contributed to his transformation.$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-549Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
