  ('8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', 'b2044359-9915-41b5-badd-087e8eb4ab2b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$What enduring symbols represent Ashoka's transformed legacy?$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-549Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, '02844c54-aa09-4498-a7e5-c676bbe54baf', NULL, 3),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', 'b2044359-9915-41b5-badd-087e8eb4ab2b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$Describe Radhagupta's character and his role in the Mauryan Empire.$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-549Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, '71474254-1f73-4c25-be46-fc9bd0d0b294', NULL, 1),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', 'b2044359-9915-41b5-badd-087e8eb4ab2b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$What specific concerns did Radhagupta raise regarding the conquest of Kalinga?$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-549Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, '71474254-1f73-4c25-be46-fc9bd0d0b294', NULL, 2),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', 'b2044359-9915-41b5-badd-087e8eb4ab2b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$How does Radhagupta's advice contrast with Ashoka's initial perspective?$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-549Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, '71474254-1f73-4c25-be46-fc9bd0d0b294', NULL, 3),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', 'b2044359-9915-41b5-badd-087e8eb4ab2b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$What was Ashoka's primary motivation for desiring the conquest of Kalinga?$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-549Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, '145905f3-2526-4ea0-b65a-d34329bc943a', NULL, 1),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '309ba1a2-eec4-402c-9562-5fe99e4431be', 'b2044359-9915-41b5-badd-087e8eb4ab2b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$How did Ashoka envision the Mauryan Empire's status after conquering Kalinga?$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-06-08T09-55-14-549Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, '145905f3-2526-4ea0-b65a-d34329bc943a', NULL, 2),
